"""NOM factory"""
from builtins import object
from taf.nms.nom import nom


class NomFactory(object):
    """NOM factory"""
    INSTANCE = None

    def __init__(self):
        self.nom = nom()

    @classmethod
    def get_instance(cls):
        """Get instance"""
        if not cls.INSTANCE:
            cls.INSTANCE = NomFactory()
        return cls.INSTANCE
